        }

        /** Bind the cell gap to a signal. */
        public Config spacing(Signal<Float> spacing) {
            this.spacing = spacing;
            return this;
        }

        /** Set a static column count (equal {@code 1fr} tracks). */
        public Config columns(int columns) {
